param([int]$Rounds=3,[int]$TimeoutMs=3000,[int]$Port=3100,[int]$ApiPid=0)
$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$out=Join-Path $root 'evidence/governance/copilot-v1.2/p9/instrumentation/runtime';New-Item -ItemType Directory -Path $out -Force|Out-Null
if($ApiPid -eq 0){$pidLine=(netstat -ano|Select-String ":$Port\s+.*LISTENING"|Select-Object -First 1);if(-not $pidLine){throw "DIAGNOSTIC_API_LISTENER_NOT_FOUND_PORT_$Port"};$ApiPid=[int](($pidLine.ToString()-split '\s+')[-1])}
$samples=@();$probeOut=Join-Path $out 'client-probe.json';$base="http://127.0.0.1:$Port/api/v1";$probe=Start-Process node.exe -ArgumentList @('scripts/instrument-basic-isolation.mjs',$Rounds,$TimeoutMs,$probeOut,$base) -WorkingDirectory $root -WindowStyle Hidden -PassThru
while(-not $probe.HasExited){$counter=Get-Counter '\Processor(_Total)\% Processor Time','\System\Processor Queue Length','\System\Context Switches/sec','\Memory\Available MBytes','\Memory\Pages/sec','\PhysicalDisk(_Total)\Avg. Disk Queue Length','\PhysicalDisk(_Total)\Disk Bytes/sec','\Network Interface(*)\Bytes Total/sec' -MaxSamples 1;$api=Get-Process -Id $ApiPid -ErrorAction SilentlyContinue;$top=@(Get-Process|Sort-Object CPU -Descending|Select-Object -First 8 Id,ProcessName,CPU,WorkingSet64);$get={param($pattern)(($counter.CounterSamples|Where-Object Path -like $pattern|Measure-Object CookedValue -Sum).Sum)};$samples+=,[ordered]@{at=(Get-Date).ToUniversalTime().ToString('o');cpuPercent=[math]::Round((&$get '*processor(_total)*'),2);processorQueue=[math]::Round((&$get '*system*processor queue length'),2);contextSwitchesPerSec=[math]::Round((&$get '*system*context switches/sec'),2);availableMemoryMB=[math]::Round((&$get '*memory*available mbytes'),2);pagesPerSec=[math]::Round((&$get '*memory*pages/sec'),2);diskQueue=[math]::Round((&$get '*physicaldisk(_total)*avg. disk queue length'),3);diskBytesPerSec=[math]::Round((&$get '*physicaldisk(_total)*disk bytes/sec'),2);networkBytesPerSec=[math]::Round((&$get '*network interface*bytes total/sec'),2);apiPid=$ApiPid;apiCpuSec=if($api){$api.CPU}else{$null};apiWorkingSetMB=if($api){[math]::Round($api.WorkingSet64/1MB,2)}else{$null};apiPrivateMB=if($api){[math]::Round($api.PrivateMemorySize64/1MB,2)}else{$null};apiThreads=if($api){$api.Threads.Count}else{$null};apiHandles=if($api){$api.Handles}else{$null};nodeProcessCount=@(Get-Process node -ErrorAction SilentlyContinue).Count;topCpuProcesses=$top};Start-Sleep -Milliseconds 250;$probe.Refresh()}
$probe.WaitForExit();$samples|ConvertTo-Json -Depth 8|Set-Content -LiteralPath (Join-Path $out 'resource-telemetry.json') -Encoding utf8;$serverTelemetry=Join-Path $out 'server-telemetry.jsonl';$summary=[ordered]@{contract='agm-basic-isolation-technical-instrumentation.v2';generatedAt=(Get-Date).ToUniversalTime().ToString('o');apiPid=$ApiPid;port=$Port;probeExitCode=$probe.ExitCode;resourceSamples=$samples.Count;serverTelemetryPresent=(Test-Path $serverTelemetry);captures=@('CPU_SATURATION','EVENT_LOOP_LAG','NODE_GC_PAUSE','PROCESS_SCHEDULING','MEMORY_PRESSURE','DISK_IO_CONTENTION','NETWORK_AND_DB_PATH_TOTAL','CLIENT_TIMEOUT_HARNESS','BACKGROUND_PROCESS_INTERFERENCE','EXACT_UTC_TIMESTAMPS','CORRELATION_ID');externalWrites=0;secretAccess=0;basicSourceModified=$false;productionModified=$false};$summary|ConvertTo-Json -Depth 6|Set-Content -LiteralPath (Join-Path $out 'instrumentation-readiness.json') -Encoding utf8
if($probe.ExitCode-ne 0){exit $probe.ExitCode};if(-not(Test-Path $serverTelemetry)){throw'SERVER_TELEMETRY_MISSING'};Write-Output 'TECHNICAL INSTRUMENTATION - PASS / READY FOR CONTROLLED REPRODUCTION'
